import com.crowdin.client.core.http.impl.json.JsonTransformer;
import com.crowdin.client.core.http.impl.json.JacksonJsonTransformer;
import com.fasterxml.jackson.core.JsonParseException;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;

public class JacksonJsonTransformerTest {

    @Test
    public void parseNonNullJsonTest() throws Exception {
        JsonTransformer transformer = new JacksonJsonTransformer();
        String json = "{\"name\": \"test-name\"}";
        TestObject testObject = transformer.parse(json, TestObject.class);

        assertNotNull(testObject);
        assertEquals("test-name", testObject.getName());
    }

    @Test(expected = JsonParseException.class)
    public void parseBadJsonTest() throws Exception {
        JsonTransformer transformer = new JacksonJsonTransformer();
        String json = "not a json";
        transformer.parse(json, TestObject.class);
    }

    @Test
    public void parseNullJsonTest() throws Exception {
        JsonTransformer transformer = new JacksonJsonTransformer();
        String json = null;
        TestObject testObject = transformer.parse(json, TestObject.class);

        assertNull(testObject);
    }

    @Test
    public void convertNonNullObjectTest() throws Exception {
        JsonTransformer transformer = new JacksonJsonTransformer();
        TestObject testObject = new TestObject();
        testObject.setName("test-name");

        String json = transformer.convert(testObject);
        assertNotNull(json);
        assertEquals("{\"name\":\"test-name\"}", json);
    }

    @Test
    public void convertNullObjectTest() throws Exception {
        JsonTransformer transformer = new JacksonJsonTransformer();
        String json = transformer.convert(null);
        assertNull(json);
    }
}

public class TestObject {
    private String name;

    public String getName() {
        return name;
    }

    public void setName(String name) {
        this.name = name;
    }
}
